const rl = require("readline").createInterface({ input: process.stdin });
var iter = rl[Symbol.asyncIterator]();
const readline = async () => (await iter.next()).value;

void (async function () {
  const nums = (await readline()).split(" ").map(Number);
  const [x, y] = (await readline()).split(" ").map(Number);

  const rows = nums[0];
  const cols = nums[1];

  const graph = new Array(rows * cols).fill(-1);

  let start = 0;
  for (let i = 2; i < nums.length; i += 2) {
    const gray = nums[i];
    const len = nums[i + 1];

    graph.fill(gray, start, start + len);
    start += len;
  }

  console.log(graph[x * cols + y]);
})();

Java:
import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int[] nums = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();
    int[] pos = Arrays.stream(sc.nextLine().split(" ")).mapToInt(Integer::parseInt).toArray();

    int rows = nums[0];
    int cols = nums[1];

    int[] graph = new int[rows * cols];

    int start = 0;

    for (int i = 2; i < nums.length; i += 2) {
      // 灰阶值
      int gray = nums[i];
      // 该灰阶值从左到右，从上到下（可理解为二维数组按行存储在一维矩阵中）的连续像素个数
      int len = nums[i + 1];
      Arrays.fill(graph, start, start + len, gray);
      start += len;
    }

    // 将二维坐标转为一维坐标
    int target = pos[0] * cols + pos[1];
    System.out.println(graph[target]);
  }
}

C:
#include <stdio.h>

int main() {
    int rows, cols;
    scanf("%d %d", &rows, &cols);

    int graph[rows * cols];
    int start = 0;

    int gray;
    int len;
    while (scanf("%d %d", &gray, &len)) {
        for (int i = start; i < start + len; i++) {
            graph[i] = gray;
        }

        start += len;

        if (getchar() != ' ') break;
    }

    int x, y;
    scanf("%d %d", &x, &y);

    printf("%d\n", graph[x * cols + y]);

    return 0;
}
